const body = $input.first().json.body || $input.first().json;

// destinoNombre es la ciudad libre (ej: "París", "Buenos Aires")
// destinoIATA es opcional — si viene, se usa para guardar en el back
const destinoNombre = (body.destinoNombre || '').replace(/\s*\(.*?\)\s*/g, '').trim();
const destinoIATA = (body.destinoIATA || destinoNombre.toUpperCase().slice(0, 3)).toUpperCase();
const destinoId = body.destinoId || null;
const checkin = body.checkin || new Date(Date.now() + 30*86400000).toISOString().slice(0,10);
const checkout = body.checkout || new Date(Date.now() + 37*86400000).toISOString().slice(0,10);
const adults = body.adults || 2;
const rooms = body.rooms || 1;
const estrellas = body.estrellas || null;
const precioMax = body.precioMax || null;

if (!destinoNombre) {
  return [{ json: { error: 'Falta destinoNombre' } }];
}

return [{ json: { destinoIATA, destinoNombre, destinoId, checkin, checkout, adults, rooms, estrellas, precioMax } }];

// Extraer dest_id del primer resultado (booking-com15) o usar fallback
const raw = $input.first().json;
const ctx = $('Parsear input').first().json;

let destId = null;
try {
  const list = raw?.data || raw?.results || [];
  if (Array.isArray(list) && list.length > 0) {
    destId = list[0].dest_id || list[0].destId || list[0].id;
  }
} catch(e) {}

return [{ json: { ...ctx, destId: destId || ctx.destinoIATA } }];

// Normalizar respuesta de Booking → formato bulk del back
const raw = $input.first().json;
const ctx = $('Extraer destId').first().json;

const items = [];
const hotelsRaw = raw?.data?.hotels || raw?.hotels || raw?.data || [];

for (const h of (Array.isArray(hotelsRaw) ? hotelsRaw.slice(0, 10) : [])) {
  const prop = h.property || h;
  const nombre = prop.name || prop.hotel_name || h.name;
  if (!nombre) continue;

  const precio = prop.priceBreakdown?.grossPrice?.value
    || prop.price
    || prop.gross_amount
    || h.min_total_price
    || 0;
  const estrellas = Math.round(prop.accuratePropertyClass || prop.propertyClass || prop.class || h.class || 3);
  const rating = prop.reviewScore || prop.review_score || h.review_score || null;
  const fotos = prop.photoUrls || prop.main_photo_url || [];
  const urlImg = Array.isArray(fotos) ? fotos[0] : fotos;
  const reservaUrl = prop.url || h.url || null;
  const direccion = prop.wishlistName || prop.address || h.address || '';

  // Calcular precio por noche (Booking devuelve el total)
  const noches = Math.max(1, Math.round((new Date(ctx.checkout) - new Date(ctx.checkin)) / 86400000));
  const precioPorNoche = noches > 0 ? Math.round(precio / noches) : precio;

  items.push({
    nombre,
    destinoIATA: ctx.destinoIATA,
    estrellas: estrellas || 3,
    precioNoche: precioPorNoche || 0,
    rating: rating ? Number((rating / 1).toFixed(1)) : null,
    urlImagen: urlImg || null,
    urlReserva: reservaUrl,
    direccion,
    fuente: 'BOOKING',
  });
}

if (items.length === 0) {
  return [{ json: { items: [], hint: 'Sin resultados o RapidAPI no respondió. Verificá la key.' } }];
}

return [{ json: { items } }];
